#include <pthread.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define SIGNAL_TO_USE SIGUSR1

void signal_handler(int sig) {
    printf("\n[Handler] Thread %lu received signal %d.\n", (unsigned long)pthread_self(), sig);
}

void *thread_func(void *arg) {
    int s;
    sigset_t set;

    // Check if the signal is currently blocked (inherited from main thread)
    if ((s = pthread_sigmask(SIG_SETMASK, NULL, &set)) != 0) {
        errno = s; perror("pthread_sigmask check"); exit(EXIT_FAILURE);
    }

    if (sigismember(&set, SIGNAL_TO_USE)) {
        printf("Worker thread: Signal %d is blocked. Unblocking now.\n", SIGNAL_TO_USE);
    }

    // Unblock SIGUSR1 in this specific thread
    sigemptyset(&set);
    sigaddset(&set, SIGNAL_TO_USE);

    if ((s = pthread_sigmask(SIG_UNBLOCK, &set, NULL)) != 0) {
        errno = s; fprintf(stderr, "Error unblocking signal: %s\n", strerror(s)); exit(EXIT_FAILURE);
    }
    printf("Worker thread: Signal %d unblocked. Waiting for pending delivery...\n", SIGNAL_TO_USE);

    // Give time for the pending signal to be delivered
    sleep(1);
    return NULL;
}

int main() {
    pthread_t tid;
    sigset_t set, oldset;
    int s;

    // 1. Establish signal handler for SIGUSR1
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGNAL_TO_USE, &sa, NULL) == -1) {
        perror("sigaction"); return 1;
    }

    // 2. Block SIGUSR1 in the main thread (new threads will inherit this block)
    sigemptyset(&set);
    sigaddset(&set, SIGNAL_TO_USE);

    if ((s = pthread_sigmask(SIG_BLOCK, &set, &oldset)) != 0) {
        errno = s; fprintf(stderr, "Error blocking signal: %s\n", strerror(s)); return 1;
    }
    printf("Main thread: Blocked signal %d before thread creation.\n", SIGNAL_TO_USE);

    // 3. Create worker thread
    if ((s = pthread_create(&tid, NULL, thread_func, NULL)) != 0) {
        errno = s; fprintf(stderr, "Error creating thread: %s\n", strerror(s)); return 1;
    }

    // 4. Send the signal. It remains pending because the main thread is blocked, 
    // and the OS will wait for an unblocked thread to receive it.
    printf("Main thread: Sending signal %d to the process.\n", SIGNAL_TO_USE);
    if (raise(SIGNAL_TO_USE) != 0) {
        perror("raise");
    }

    // 5. Wait for the thread to process the signal and exit
    pthread_join(tid, NULL);

    // 6. Restore original mask in main thread
    pthread_sigmask(SIG_SETMASK, &oldset, NULL);
    printf("Main thread exiting.\n");

    return 0;
}
